    // /// Dofs: w(0) w(1) w'(0) w'(1) w''(0) w''(1)
    // template<unsigned BOUNDARY_ORDER>
    // void BernadouElementBasis<BOUNDARY_ORDER>::hermite_shape_1d_5(
